def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count replacements by 1, 2, 3 with unequal edge-adjacent cells.

    H and W are positive and H * W <= 200. Fixed digits are preserved.
    Return the number of valid configurations modulo 998244353.
    """
    mod = 998244353
    # The frontier width is at most sqrt(200), regardless of orientation.
    if W > H:
        grid = [''.join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    # A fixed equal pair makes every possible completion invalid.
    for r in range(H):
        for c in range(W):
            value = grid[r][c]
            if value != '?':
                if c and grid[r][c - 1] == value:
                    return 0
                if r and grid[r - 1][c] == value:
                    return 0

    # Each two-bit slot holds one color; zero denotes an unfilled cell.
    # Before a cell is processed the oldest slot is its upper neighbor,
    # and the newest slot is its left neighbor (except at row boundaries).
    high_shift = 2 * (W - 1)
    keep_mask = (1 << high_shift) - 1
    dp = {0: 1}
    for row in grid:
        for c, value in enumerate(row):
            colors = (1, 2, 3) if value == '?' else (int(value),)
            following = {}
            for state, ways in dp.items():
                above = state >> high_shift
                left = (state & 3) if c else 0
                prefix = (state & keep_mask) << 2
                for color in colors:
                    if color != above and color != left:
                        new_state = prefix | color
                        following[new_state] = (following.get(new_state, 0) + ways) % mod
            dp = following
            if not dp:
                return 0
    return sum(dp.values()) % mod

from typing import List


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    """Count length-m lowercase strings by their LCS length with s.

    Return n+1 counts modulo 998244353. The constraints are
    1 <= n <= 10, 1 <= m <= 100, and len(s) == n.
    """
    mod = 998244353
    positions = {}
    for i, char in enumerate(s):
        positions[char] = positions.get(char, 0) | (1 << i)

    # A row of the usual LCS DP is nondecreasing with increments 0 or 1.
    # Bit i records the increment at prefix s[:i+1]. Thus only 2**n
    # different rows are possible, and the row sum is its bit count.
    size = 1 << n
    other_letters = 26 - len(positions)
    transitions = []
    for state in range(size):
        destinations = {}
        if other_letters:
            destinations[state] = other_letters
        for char_mask in positions.values():
            # Bit-parallel LCS update for appending this character.
            union = state | char_mask
            next_state = union & ~(union - ((state << 1) | 1))
            destinations[next_state] = destinations.get(next_state, 0) + 1
        transitions.append(tuple(destinations.items()))

    counts = [0] * size
    counts[0] = 1
    for _ in range(m):
        following = [0] * size
        for state, count in enumerate(counts):
            if count:
                for destination, multiplicity in transitions[state]:
                    following[destination] += count * multiplicity
        counts = [value % mod for value in following]

    answer = [0] * (n + 1)
    for state, count in enumerate(counts):
        answer[state.bit_count()] += count
    return [value % mod for value in answer]

